const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

export const APPLIANCES: DeviceCategory[] = ROWS.map(([id, label, fam, on, standby, keywords]) => {
  const f = FAMILIES[fam];
  return {
    id,
    label: cap(label),
    keywords,
    wattsOn: on,
    wattsStandby: standby,
    wattsLow: Math.max(0.1, Math.round(on * 0.45 * 10) / 10),
    wattsHigh: Math.round(on * 1.8 * 10) / 10,
    dutyCycle: f.duty,
    ...(f.thermo ? { thermostatic: true } : {}),
    group: f.group,
    icon: f.icon,
    source: `Typical draw for a ${label} (U.S. DOE Energy Saver appliance table, ENERGY STAR, manufacturer nameplates); wide band.`,
    action: { label: f.label, type: f.type, cost: f.cost, savingsFraction: f.save, note: f.note },
  };
});

/**
 * The last resort: something powered that matches nothing above. Its band is
 * very wide on purpose, so the model's own watt reading for the unit it sees
 * carries the estimate, and it is never more confident than a guess.
 */
export const OTHER_DEVICE: DeviceCategory = {
  id: "other_device",
  label: "Other powered device",
  keywords: [],
  wattsOn: 40,
  wattsStandby: 2,
  wattsLow: 2,
  wattsHigh: 2000,
  dutyCycle: 1,
  group: "specialty",
  icon: "plug",
  source: "No catalog entry: priced from the model's own reading of the unit, inside a very wide band.",
  action: { label: "Switch off or unplug when not needed", type: "policy", cost: 0, savingsFraction: 0.7, note: "If nobody needs it overnight, off is free." },
};

export const APPLIANCE_COUNT = ROWS.length;
